"""Copy the trained model into the app (src/model.js) and the parity data into tests/."""
import pathlib, shutil
HERE = pathlib.Path(__file__).resolve().parent
m = (HERE / 'model.json').read_text(encoding='utf8')
(HERE.parent / 'src' / 'model.js').write_text(
    '/* Auto-generated by ml/train.py - do not edit */\nvar SCAMSHIELD_MODEL=' + m +
    ';\nif(typeof module!=="undefined")module.exports=SCAMSHIELD_MODEL;\n', encoding='utf8')
shutil.copy(HERE / 'parity.json', HERE.parent / 'tests' / 'parity.json')
print('exported model to src/model.js and tests/parity.json')
